'use strict'

import InputManager from '../service/input-manager'
import resource from '../resource'
import { listenMenuKeys } from './menu-keys'
import { NES_COLOURS } from '../model/resource/nes-colours'
import { NES_PIXEL } from '../constant'

// The title screen of the ROM (sprites title_*, see tools/sprites/title.json), as it moves, in frames of the NES
// (60 per second)
const FRAME = 1000 / 60
const BACKGROUND_COLOUR = `#${NES_COLOURS[0x36]}`
// The shine of the logo: colour 2 of the background palette 1, frames of each colour
const SHINE = [['27', 6], ['37', 12], ['27', 6], ['17', 6], ['07', 12], ['17', 16]]
const SHINE_FRAMES = SHINE.reduce((sum, [, frames]) => sum + frames, 0)
// The waterfall (NES pixels): its crest changes every 8 frames; 3 waves go down 2 pixels a frame, one after the
// other, from the crest to the bottom of the screen in 25 frames (a new one every 8 or 9 frames), their picture
// changing on the way
const WATERFALL_X = 80
const CREST_Y = 161
const CREST_FRAMES = 8
const WAVE_Y = 171
const WAVE_SPEED = 2
const WAVE_FRAMES = 25
const WAVE_PHASES = [0, 9, 17]
const WAVE_PICTURES = [[0, 0], [4, 1], [8, 2]]
const LAYERS = ['title_background_0', 'title_background_2', 'title_background_3', 'title_sprites_2', 'title_sprites_3']

// Shown when the page opens and after "retry": the game starts on Start
class TitleScreen {
  constructor (onStart) {
    this.onStart = onStart
    this.visible = false
    this.stopListening = undefined
    this.shownAt = 0
  }

  show () {
    this.visible = true
    this.shownAt = performance.now()
    this.stopListening?.()
    this.stopListening = listenMenuKeys({
      [InputManager.ACTION_START]: () => {
        this.hide()
        this.onStart()
      }
    })
  }

  hide () {
    this.visible = false
    this.stopListening?.()
    this.stopListening = undefined
  }

  draw (context, width, height) {
    const frame = Math.floor((performance.now() - this.shownAt) / FRAME)
    context.fillStyle = BACKGROUND_COLOUR
    context.fillRect(0, 0, width, height)

    const drawAt = (name, image, x, y) => {
      const sprite = resource.getSprite(name)
      sprite?.images[image]?.draw(context, x * NES_PIXEL, y * NES_PIXEL, sprite.images[image].width * NES_PIXEL, sprite.images[image].height * NES_PIXEL)
    }
    drawAt(LAYERS[0], 0, 0, 0)
    drawAt(`title_background_1_${shineColour(frame)}`, 0, 0, 0)
    for (const layer of LAYERS.slice(1)) {
      drawAt(layer, 0, 0, 0)
    }

    drawAt('title_waterfall_crest', Math.floor(frame / CREST_FRAMES) % 2, WATERFALL_X, CREST_Y)
    for (const phase of WAVE_PHASES) {
      const age = (frame + WAVE_FRAMES - phase) % WAVE_FRAMES
      const picture = WAVE_PICTURES.findLast(([from]) => age >= from)[1]
      drawAt('title_waterfall_wave', picture, WATERFALL_X, WAVE_Y + WAVE_SPEED * age)
    }
  }
}

// The colour of the shine of the logo at a frame of the title screen
export function shineColour (frame) {
  let left = frame % SHINE_FRAMES
  for (const [colour, frames] of SHINE) {
    if (left < frames) {
      return colour
    }
    left -= frames
  }
}

export { TitleScreen }
